using System;

namespace MyPowerMillPlugin.Model
{
    /// <summary>
    /// Decision outputs generated by the Domain ML Model seam.
    /// Injected directly into PowerMill strategy macros and toolpaths.
    /// </summary>
    public class ModelInferenceResult
    {
        public string PredictedHoleType { get; set; } = "BlindHole";
        public double ConfidenceScore { get; set; } = 0.95;

        // Recommended CAM Machining Parameters
        public string RecommendedStrategy { get; set; } = "DeepDrillPeck"; // SingleShot, DeepDrillPeck, HelicalInterpolation, Reaming
        public double RecommendedPeckDepthMm { get; set; } = 3.5;
        public double RecommendedSpindleRpm { get; set; } = 2850.0;
        public double RecommendedFeedMmPerMin { get; set; } = 420.0;
        public double RecommendedSurfaceSpeedVc { get; set; } = 90.0; // m/min
        public double RecommendedFeedPerToothFz { get; set; } = 0.075; // mm/tooth

        // Risk & Operational Metrics
        public double ToolBreakageRiskScore { get; set; } = 0.12; // 0.0 to 1.0
        public double ChatterProbability { get; set; } = 0.08;
        public double EstimatedCycleTimeSeconds { get; set; } = 8.4;
        public double CycleTimeSavedPercentage { get; set; } = 18.5;

        // Generated PowerMill Automation Command
        public string PowerMillMacroCommand { get; set; } = "";
    }
}
